def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(x for row in grid for x in row), key=lambda x: sum(row.count(x) for row in grid))

    # Extend each diagonal stroke of matching-colored cells in both directions.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w) or grid[nr][nc] != color:
                    continue
                # Extend from both ends of this observed diagonal pair.
                for sign in (-1, 1):
                    rr, cc = (r, c) if sign == -1 else (nr, nc)
                    step_r, step_c = sign * dr, sign * dc
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] not in (bg, color):
                            break
                        out[rr][cc] = color
                        rr += step_r
                        cc += step_c
    return out
